package dev.slne.surf.nats

/**
 * Marks the API that code generated by the `dev.slne.surf.nats` Gradle plugin calls.
 *
 * Unlike [InternalNatsApi], these declarations form the binary contract between generated code in consumer artifacts
 * and the surf-nats runtime that loads it. They are covered by ABI validation and change only in binary-compatible
 * ways. Hand-written code must not use them.
 */
@RequiresOptIn(
    level = RequiresOptIn.Level.ERROR,
    message = "API for code generated by the surf-nats Gradle plugin."
)
@Retention(AnnotationRetention.BINARY)
@Target(
    AnnotationTarget.CLASS,
    AnnotationTarget.FUNCTION,
    AnnotationTarget.PROPERTY,
    AnnotationTarget.CONSTRUCTOR
)
public annotation class NatsGeneratedApi
